    expect(scrollTo).toHaveBeenCalledWith(expect.objectContaining({ left: expect.any(Number), behavior: 'smooth' }));
    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
  });
